/bin/bash -c "python3 - <<'PY'
import math, json

def rotate(a):
    return [list(row) for row in zip(*a)][::-1]
def rotate_n(a,k):
    for _ in range(k%4): a=rotate(a)
    return a

def normalize(a):
    norm=math.sqrt(sum(v*v for row in a for v in row))
    return [[v/norm for v in row] for row in a]
def dist(a,b):
    return math.sqrt(sum((u-v)**2 for x,y in zip(a,b) for u,v in zip(x,y)))

def tent_primitive(x,c,h):
    t=(x-c)/h
    if t<=-1: return 0.0
    if t<0: return h*(t+1)**2/2
    if t<1: return h*(1-(1-t)**2/2)
    return h

d=64
bumps=[(3/8,3/8,1),(9/16,3/8,2),(7/16,5/8,3)]
h=1/32
f0=[[sum(w*d*d*(tent_primitive((i+1)/d,cx,h)-tent_primitive(i/d,cx,h))*(tent_primitive((j+1)/d,cy,h)-tent_primitive(j/d,cy,h)) for cx,cy,w in bumps) for j in range(d)] for i in range(d)]
f0=normalize(f0)
test=rotate_n(f0,1)
for label,training in [(0,f0),(1,rotate_n(f0,2))]:
    entries=[{'training_inverse_power':b_i,'test_inverse_power':b,'distance':dist(rotate_n(training,b_i),rotate_n(test,b))} for b_i in [0,3] for b in [0,3]]
    print(json.dumps({'training_label':label,'candidate_distances':entries,'minimum_distance':min(x['distance'] for x in entries)}))
PY"
